import Foundation

@main
struct TestMain {
    static func main() async throws {
        let client = RPCClient(maxConcurrent: 4)

        // Test deduplication
        let req = RPCRequest(id: "req-1", method: "getUser", payload: "uid=42")

        var callCount = 0
        let transport: @Sendable (RPCRequest) async throws -> RPCResponse = { r in
            try await Task.sleep(nanoseconds: 30_000_000)
            return RPCResponse(id: r.id, result: "user-data", isError: false)
        }

        async let res1 = client.send(request: req, transport: transport)
        async let res2 = client.send(request: req, transport: transport)

        let (r1, r2) = try await (res1, res2)
        assert(r1.result == "user-data")
        assert(r2.result == "user-data")
        print("Swift 6 Multi-Module RPC Test Passed!")
    }
}
